"""A theory fitted to many paradigms at once (docs/auto_open/PLAN.md §5, Phase 2b).

A chain's data are **blocks**: the literature data the closed campaign started from (E, forced
choice) and each experiment's paradigm. Every block keeps its frozen link (`src.rsa_open.links`).
A theory has one set of parameters for every block; each block has its own copy of its link's
parameters (``temperature@exp1``), since a response process belongs to a paradigm, not to a
theory. So:

- `fit_corpus` samples the theory's parameters once and each block's link parameters, with
  the closed campaign's NUTS settings, and keeps every trial's pointwise log-likelihood;
- `heldout_lpd` scores trials a fit did not see: the log of the posterior-mean probability of
  each response, as the closed loop's `src.rsa.evaluate_heldout.heldout_lpd`;
- `assign_folds` and `cv_corpus` are the closed loop's grouped cross-validation made per block:
  whole units (E's display units, `src.rsa.split.unit_keys`; a paradigm's design units) go to
  ``k`` folds balanced within each block, and fold f's fit trains on every block without its
  fold-f trials, so a candidate costs ``k`` fits whatever the number of blocks;
- `standing` ranks theories on the newest block and applies the accountability rule (PLAN §5):
  a theory is **eligible** only when, on every earlier block, it is within ``guard_k`` clustered
  standard errors of that block's best theory. The closed loop's guard pooled every earlier
  trial into one comparison; here each paradigm, E included, is guarded on its own.
"""

from __future__ import annotations

import time
from dataclasses import dataclass, field
from functools import cached_property
from typing import Any, Callable, Dict, List, Mapping, Optional, Sequence, Tuple

import arviz as az
import jax
import jax.numpy as jnp
import numpy as np
import numpyro
from numpyro.infer import MCMC, NUTS

from src.models.pymc_inference import convergence_problems
from src.rsa.context import Context
from src.rsa.fit import FitSettings
from src.rsa_open.fit import OBSERVED_SITE, OpenData, TheoryModel, _latent, _split, pointwise_log_lik
from src.rsa_open.links import LinkLikelihood

GUARD_K = 4.0  # PI 2026-10-21: no more than 4 clustered SEs worse on any earlier paradigm
DEFAULT_FOLDS = 5
MAX_HELDOUT_DRAWS = 400  # as the closed loop's held-out score


@dataclass(frozen=True)
class Block:
    """One paradigm's trials under its frozen link. ``units`` are the cross-validation and
    standard-error units (one per trial), ``sources`` the data sources within the block, ``fixed``
    the link parameters held at a value instead of fitted (the literature's temperature,
    `literature_block`)."""

    name: str
    link: LinkLikelihood
    contexts: Tuple[Context, ...]
    responses: Tuple[Mapping[str, Any], ...]
    units: Tuple[str, ...]
    sources: Tuple[str, ...] = ()
    fixed: Tuple[Tuple[str, float], ...] = ()

    def __post_init__(self) -> None:
        n = len(self.contexts)
        if not n:
            raise ValueError(f"block {self.name}: no trials")
        if "@" in self.name:
            raise ValueError(f"block {self.name}: '@' names a block's link parameters")
        if len(self.responses) != n or len(self.units) != n:
            raise ValueError(f"block {self.name}: {n} scenes, {len(self.responses)} responses, {len(self.units)} units")
        if self.sources and len(self.sources) != n:
            raise ValueError(f"block {self.name}: {len(self.sources)} sources for {n} trials")
        for k, _ in self.fixed:
            if k not in self.link.params:
                raise ValueError(f"block {self.name}: fixed {k!r} is not a parameter of the {self.link.name} link")

    @property
    def fixed_params(self) -> Dict[str, float]:
        return {k: float(v) for k, v in self.fixed}

    @property
    def free_link_params(self) -> Dict[str, Any]:
        """The link parameters fitted for this block (name -> prior)."""
        return {k: d for k, d in self.link.params.items() if k not in self.fixed_params}

    @property
    def n(self) -> int:
        return len(self.contexts)

    @cached_property
    def data(self) -> OpenData:
        return OpenData.build(self.contexts, self.responses, self.link)

    def param(self, name: str) -> str:
        """This block's copy of a link parameter."""
        return f"{name}@{self.name}"

    def subset(self, rows: Sequence[int]) -> "Block":
        rows = list(rows)
        return Block(self.name, self.link, tuple(self.contexts[i] for i in rows),
                     tuple(self.responses[i] for i in rows), tuple(self.units[i] for i in rows),
                     tuple(self.sources[i] for i in rows) if self.sources else (), self.fixed)


def check_blocks(blocks: Sequence[Block]) -> None:
    names = [b.name for b in blocks]
    if len(set(names)) != len(names):
        raise ValueError(f"block names repeat: {names}")
    if not blocks:
        raise ValueError("no blocks")


# E is the reference block (PI 2026-10-22): its link's temperature is 1, so on E every theory is its
# closed original (the port equals it at temperature 1) and each new paradigm's temperature is
# relative to E. Fitted on E alone, a free temperature traded off against a theory's own sharpness
# (rsa_l1_shared_prior: alpha 0.15 at temperature 2.5, against 1.4 at 1) and one fit stalled for
# hours; a theory in which people sharpen or soften their beliefs into a choice says so with a
# parameter of its own, which every paradigm then tests.
LITERATURE_FIXED = (("temperature", 1.0),)


def literature_block(path=None, name: str = "E") -> Block:
    """The literature's forced-choice trials (the closed loader) as a choice-link block, its
    temperature fixed (`LITERATURE_FIXED`)."""
    from src.rsa.dataset import DEFAULT_TRIALS_CSV, load_forced_choice
    from src.rsa.split import unit_keys
    from src.rsa_open.links import likelihood

    trials = load_forced_choice(path or DEFAULT_TRIALS_CSV)
    frame = trials.frame
    sources = frame["source"].astype(str) if "source" in frame.columns else ["pragmods"] * len(frame)
    return Block(name, likelihood("choice"), tuple(trials.contexts), tuple({"choice": int(c)} for c in trials.choices),
                 tuple(unit_keys(frame).astype(str)), tuple(str(s) for s in sources), LITERATURE_FIXED)


def paradigm_block(name: str, paradigm, rows: Sequence[Mapping[str, Any]]) -> Block:
    """An experiment's test trials (`src.rsa_open.screens.page_rows`) under its paradigm's link;
    a trial's unit is the design unit it showed."""
    from src.rsa_open.paradigm import paradigm_likelihood
    from src.rsa_open.screens import scenes_and_responses

    tests = [r for r in rows if r.get("phase") == "test"]
    contexts, responses = scenes_and_responses(tests)
    return Block(name, paradigm_likelihood(paradigm), tuple(contexts), tuple(responses),
                 tuple(f"unit{r['unit']}" for r in tests), tuple(name for _ in tests))


# --------------------------------------------------------------------------- the joint fit

def _corpus_model(theory: TheoryModel, blocks: Sequence[Block]):
    params = {name: numpyro.sample(name, prior) for name, prior in theory.params.items()}
    total = 0.0
    for block in blocks:
        link = block.link
        fixed = block.fixed_params
        lp = {k: jnp.asarray(fixed[k]) if k in fixed else numpyro.sample(block.param(k), prior)
              for k, prior in link.params.items()}
        tp = {k: params[k] for k in theory.params}
        for group, enc in zip(block.data.groups, block.data.encoded):
            total = total + jnp.sum(link.log_lik(_latent(theory, link, tp, group), lp, enc, group.arrays,
                                                 jnp.asarray(group.classes)))
    numpyro.factor(OBSERVED_SITE, total)


def block_draws(flat: Mapping[str, np.ndarray], theory: TheoryModel, block: Block) -> Dict[str, np.ndarray]:
    """One block's view of flat posterior draws: the theory's parameters and its link's, unsuffixed."""
    out = {k: flat[k] for k in theory.params}
    n = len(next(iter(flat.values())))
    fixed = block.fixed_params
    out.update({k: np.full(n, fixed[k]) if k in fixed else flat[block.param(k)] for k in block.link.params})
    return out


@dataclass
class CorpusFit:
    theory_name: str
    blocks: List[str]
    idata: Any
    param_names: List[str]
    convergence_problems: List[str]
    offsets: Dict[str, Tuple[int, int]] = field(default_factory=dict)  # block -> (start, stop) in log_likelihood
    timing: Dict[str, float] = field(default_factory=dict)
    """warmup_sec (compilation included), sampling_sec, and the leapfrog steps of each phase
    (per iteration, the most any chain took); empty for a fit recorded before they were kept."""

    @property
    def converged(self) -> bool:
        return not self.convergence_problems

    @property
    def diagnostics(self):
        """Convergence numbers (`src.models.pymc_inference.ConvergenceDiagnostics`) over the free parameters."""
        from src.models.pymc_inference import convergence_diagnostics

        return convergence_diagnostics(self.idata, self.param_names)

    @property
    def near_miss(self) -> bool:
        """A failed fit close enough to the gate that a refit at smaller steps may pass (main's rule)."""
        from src.models.pymc_inference import is_near_miss

        return not self.converged and is_near_miss(self.diagnostics)

    def sampler_report(self):
        """Steps per draw, step size and correlated parameters (`src.rsa_open.sampler`), or None."""
        from src.rsa_open.sampler import report_of

        return report_of(self.idata, self.param_names)

    def flat(self) -> Dict[str, np.ndarray]:
        post = self.idata.posterior
        return {k: np.asarray(post[k]).reshape(-1) for k in post.data_vars}

    def pointwise(self, block: str) -> np.ndarray:
        """(draws, trials) log-likelihood of one block's trials."""
        start, stop = self.offsets[block]
        ll = np.asarray(self.idata.log_likelihood[OBSERVED_SITE])
        return ll.reshape(-1, ll.shape[-1])[:, start:stop]


def fit_corpus(theory: TheoryModel, blocks: Sequence[Block],
               settings: FitSettings = FitSettings(dense_mass=True),
               init: Optional[Mapping[str, float]] = None,
               on_warmup: Optional[Callable[[Dict[str, Any]], None]] = None) -> CorpusFit:
    """NUTS on the corpus; with ``init`` (constrained values of sampled sites) every chain starts
    there instead of at random. Warmup and sampling run as two calls (sampling reuses warmup's
    compiled kernel), each timed with its leapfrog steps; ``on_warmup`` receives the warmup's
    `src.rsa_open.sampler.warmup_report` (as JSON) and timing once warmup ends, so a fit killed
    while sampling still says what its geometry was."""
    check_blocks(blocks)
    clash = sorted(set(theory.params) & {b.param(k) for b in blocks for k in b.link.params})
    if clash:
        raise ValueError(f"theory parameters {clash} collide with block link parameters")
    from numpyro.infer import init_to_uniform, init_to_value

    strategy = init_to_value(values={k: float(v) for k, v in init.items()}) if init else init_to_uniform
    kernel = NUTS(_corpus_model, target_accept_prob=settings.target_accept, dense_mass=settings.dense_mass,
                  init_strategy=strategy)
    mcmc = MCMC(kernel, num_warmup=settings.num_warmup, num_samples=settings.num_samples,
                num_chains=settings.num_chains, chain_method="vectorized", progress_bar=False)
    names = [*theory.params, *(b.param(k) for b in blocks for k in b.free_link_params)]
    t0 = time.perf_counter()
    mcmc.warmup(jax.random.PRNGKey(settings.seed), theory, list(blocks), collect_warmup=True,
                extra_fields=("num_steps", "adapt_state.step_size"))
    warm = mcmc.get_extra_fields(group_by_chain=True)
    warm_steps = np.asarray(warm["num_steps"])
    timing = dict(warmup_sec=time.perf_counter() - t0, warmup_steps=float(warm_steps.max(axis=0).sum()))
    if on_warmup is not None:
        from src.rsa_open.sampler import warmup_report

        warm_samples = {k: np.asarray(v) for k, v in mcmc.get_samples(group_by_chain=True).items()}
        on_warmup(dict(report=warmup_report(warm_samples, warm_steps, np.asarray(warm["adapt_state.step_size"]),
                                            names).to_json(), timing=timing))
    t1 = time.perf_counter()
    mcmc.run(mcmc.post_warmup_state.rng_key, theory, list(blocks),
             extra_fields=("diverging", "num_steps", "adapt_state.step_size"))
    extra = mcmc.get_extra_fields(group_by_chain=True)
    n_steps = np.asarray(extra["num_steps"])
    timing.update(sampling_sec=time.perf_counter() - t1, sampling_steps=float(n_steps.max(axis=0).sum()))
    samples = {k: np.asarray(v) for k, v in mcmc.get_samples(group_by_chain=True).items()}
    chains, draws = next(iter(samples.values())).shape[:2]
    flat = {k: v.reshape(chains * draws) for k, v in samples.items()}
    lls, offsets, start = [], {}, 0
    for block in blocks:
        lls.append(pointwise_log_lik(theory, block.link, block.data, block_draws(flat, theory, block)))
        offsets[block.name] = (start, start + block.n)
        start += block.n
    ll = np.concatenate(lls, axis=1)
    idata = az.from_dict(
        posterior=samples, log_likelihood={OBSERVED_SITE: ll.reshape(chains, draws, -1)},
        sample_stats={"diverging": np.asarray(extra["diverging"]), "n_steps": n_steps,
                      "step_size": np.asarray(extra["adapt_state.step_size"])})
    return CorpusFit(theory.name, [b.name for b in blocks], idata, names, convergence_problems(idata, names), offsets,
                     timing)


def heldout_lpd(theory: TheoryModel, fitted: CorpusFit, block: Block,
                max_draws: int = MAX_HELDOUT_DRAWS) -> np.ndarray:
    """(trials,) log posterior-mean probability of each of ``block``'s responses under a fit that
    did not see them; the block's link parameters are the fit's copy for that block."""
    if block.name not in fitted.blocks:
        raise ValueError(f"the fit has no link parameters for block {block.name} ({fitted.blocks})")
    flat = fitted.flat()
    n = len(next(iter(flat.values())))
    take = np.unique(np.linspace(0, n - 1, min(n, max_draws)).round().astype(int))
    draws = {k: v[take] for k, v in block_draws(flat, theory, block).items()}
    ll = pointwise_log_lik(theory, block.link, block.data, draws)
    return np.asarray(jax.scipy.special.logsumexp(ll, axis=0) - np.log(ll.shape[0]))


# --------------------------------------------------------------------------- cross-validation

def assign_folds(block: Block, k: int = DEFAULT_FOLDS, seed: int = 0) -> np.ndarray:
    """Fold of every trial of a block: whole units, balanced in trials within each source (the
    closed loop's rule, `src.rsa.loop.cv.assign_folds`)."""
    if k < 2:
        raise ValueError(f"grouped CV needs at least 2 folds, not {k}")
    units = np.asarray(block.units)
    sources = np.asarray(block.sources) if block.sources else np.full(block.n, block.name)
    rng = np.random.default_rng([seed, sum(block.name.encode())])
    fold_of_unit: Dict[str, int] = {}
    for src in sorted(set(sources)):
        names, sizes = np.unique(units[sources == src], return_counts=True)
        if len(names) < k:
            raise ValueError(f"block {block.name}, source {src}: {len(names)} units, fewer than the {k} folds")
        order = rng.permutation(len(names))
        load = np.zeros(k)
        for i in sorted(order, key=lambda i: -sizes[i]):  # largest first into the lightest fold
            f = int(np.argmin(load))
            fold_of_unit[names[i]] = f
            load[f] += sizes[i]
    return np.asarray([fold_of_unit[u] for u in units], dtype=int)


@dataclass
class CorpusCV:
    pointwise: Dict[str, np.ndarray]  # block -> (trials,) out-of-fold lpd
    converged: bool

    def elpd(self, block: str) -> float:
        return float(self.pointwise[block].sum())


def cv_corpus(theory: TheoryModel, blocks: Sequence[Block], folds: Mapping[str, np.ndarray], k: int,
              fit_fn=fit_corpus, settings: Optional[FitSettings] = None) -> CorpusCV:
    """Out-of-fold lpd of every trial of every block: fold f's fit trains on every block without
    its fold-f trials. ``fit_fn(theory, blocks, settings)`` is the fit (cached in the loop)."""
    check_blocks(blocks)
    out = {b.name: np.empty(b.n) for b in blocks}
    converged = True
    for f in range(k):
        train = [b.subset(np.where(folds[b.name] != f)[0]) for b in blocks]
        fitted = fit_fn(theory, train, settings) if settings is not None else fit_fn(theory, train)
        converged = converged and fitted.converged
        for b in blocks:
            rows = np.where(folds[b.name] == f)[0]
            if len(rows):
                out[b.name][rows] = heldout_lpd(theory, fitted, b.subset(rows))
    return CorpusCV(out, converged)


def standing(results: Mapping[str, CorpusCV], blocks: Sequence[Block], *, guard_k: float = GUARD_K) -> Dict[str, dict]:
    """Each theory's standing: ELPD-CV on the newest block (the last) and its gap to the best with
    the unit-clustered SE; on every earlier block its gap to that block's best and SE; and
    ``eligible``: within ``guard_k`` SEs of the best on every earlier block."""
    from src.models.clustered_se import cluster_dse

    check_blocks(blocks)
    if not results:
        raise ValueError("no theories to rank")
    out: Dict[str, dict] = {name: {"by_block": {}} for name in results}
    for i, block in enumerate(blocks):
        units = np.unique(np.asarray(block.units), return_inverse=True)[1]
        elpd = {n: r.elpd(block.name) for n, r in results.items()}
        top = max(elpd, key=elpd.get)
        for name, r in results.items():
            dse = 0.0 if name == top else float(cluster_dse(results[top].pointwise[block.name],
                                                            r.pointwise[block.name], units))
            out[name]["by_block"][block.name] = {"elpd_cv": elpd[name], "behind": elpd[top] - elpd[name], "dse": dse}
    newest = blocks[-1].name
    for name, o in out.items():
        new = o["by_block"][newest]
        o.update(sel_elpd=new["elpd_cv"], sel_diff=new["behind"], sel_dse=new["dse"],
                 cv_converged=results[name].converged)
        earlier = {b.name: o["by_block"][b.name] for b in blocks[:-1]}
        o["guard_failures"] = sorted(b for b, s in earlier.items() if s["behind"] > guard_k * s["dse"])
        o["eligible"] = not o["guard_failures"]
    return out

"""Loading memo model files, one compiled copy per context shape, and their contract.

A model file is a self-contained ``.py`` file that defines

* ``PARAMS`` — a non-empty dict mapping parameter names to numpyro
  distributions (the priors), and
* ``choice_probs(params, ctx)`` — for ONE trial, the probability that the
  participant chooses each object: an array of shape ``(N_OBJ,)``. ``params``
  maps each name in ``PARAMS`` to a scalar; ``ctx`` is a
  `src.rsa.context.ContextArrays` for that trial.

It writes its memo models over the domains ``OBJ`` (objects) and ``UTT``
(utterances), which it must not define: the loader executes the file once per
context shape ``(N_OBJ, N_UTT)`` with those names already bound to
``jnp.arange(N_OBJ)`` / ``jnp.arange(N_UTT)`` (memo's domains are fixed
globals, and padding contexts to one size makes 0/0 normalisations whose
gradients are NaN — see `src.rsa.context`). The harness ``vmap``s
``choice_probs`` over a shape group's trials.

The contract (`check_contract`), run with no sampling: at several parameter
draws from the priors, on every shape group, the probabilities have shape
``(N_OBJ,)`` per trial, are finite and non-negative and sum to 1, and their
gradient with respect to every parameter is finite. A model that breaks it
raises `ModelContractViolation` with the reason.
"""

from __future__ import annotations

import ast
import hashlib
import sys
import types
from pathlib import Path
from typing import Any, Dict, Mapping, Optional, Sequence, Tuple

import jax
import jax.numpy as jnp
import numpy as np
from numpyro.distributions import Distribution

from src.rsa.context import ShapeGroup

INJECTED_NAMES = ("OBJ", "UTT")
PROBABILITY_SUM_TOLERANCE = 1e-4  # memo computes in float32
NEGATIVE_TOLERANCE = 1e-6
CONTRACT_DRAWS = 4


class ModelContractViolation(ValueError):
    """A model file that does not meet the model contract (a model's failure)."""


def _defined_names(tree: ast.Module) -> set:
    """Names bound at the top level of a module (assignments, defs, imports)."""
    names = set()
    for node in tree.body:
        targets = []
        if isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, (ast.Import, ast.ImportFrom)):
            names.update((a.asname or a.name).split(".")[0] for a in node.names)
        for target in targets:
            for sub in ast.walk(target):
                if isinstance(sub, ast.Name):
                    names.add(sub.id)
    return names


class RSAModel:
    """A memo model file, compiled lazily once per context shape."""

    def __init__(self, path: Path, name: Optional[str] = None) -> None:
        self.path = Path(path).resolve()
        self.name = name or self.path.stem
        self.source = self.path.read_text(encoding="utf-8")
        self.sha = hashlib.sha256(self.source.encode("utf-8")).hexdigest()
        tree = ast.parse(self.source, filename=str(self.path))
        clash = sorted(set(INJECTED_NAMES) & _defined_names(tree))
        if clash:
            raise ModelContractViolation(
                f"{self.path.name} defines {', '.join(clash)}; the domains OBJ and UTT "
                f"are injected by the loader, sized to each context — remove the definition"
            )
        self._code = compile(self.source, str(self.path), "exec")
        self._modules: Dict[Tuple[int, int], types.ModuleType] = {}
        self._jitted: Dict[Tuple[int, int], Any] = {}

    @property
    def compiled_shapes(self) -> Tuple[Tuple[int, int], ...]:
        return tuple(sorted(self._modules))

    def module(self, shape: Tuple[int, int]) -> types.ModuleType:
        """The file executed with OBJ/UTT sized to ``shape`` = (N_OBJ, N_UTT)."""
        if shape not in self._modules:
            n_obj, n_utt = shape
            mod_name = f"rsa_model_{self.name}_{self.sha[:12]}_{n_obj}x{n_utt}"
            module = types.ModuleType(mod_name)
            module.__file__ = str(self.path)
            module.__dict__.update(OBJ=jnp.arange(n_obj), UTT=jnp.arange(n_utt))
            # memo reads its source back with inspect, which needs the module
            # registered under its name.
            sys.modules[mod_name] = module
            exec(self._code, module.__dict__)
            self._modules[shape] = module
        return self._modules[shape]

    def _any_module(self) -> types.ModuleType:
        return self.module(self.compiled_shapes[0] if self._modules else (2, 2))

    @property
    def params(self) -> Dict[str, Distribution]:
        module = self._any_module()
        params = getattr(module, "PARAMS", None)
        if not isinstance(params, Mapping) or not params:
            raise ModelContractViolation(
                f"{self.path.name} must define PARAMS, a non-empty dict of "
                f"parameter name -> numpyro distribution (the priors)"
            )
        bad = [k for k, v in params.items() if not isinstance(v, Distribution)]
        if bad:
            raise ModelContractViolation(
                f"PARAMS entries {bad} in {self.path.name} are not numpyro distributions"
            )
        return dict(params)

    def _choice_probs(self, shape: Tuple[int, int]):
        fn = getattr(self.module(shape), "choice_probs", None)
        if not callable(fn):
            raise ModelContractViolation(
                f"{self.path.name} must define choice_probs(params, ctx) returning the "
                f"probability of choosing each object, shape (N_OBJ,)"
            )
        return fn

    def group_probs(self, params: Mapping[str, Any], group: ShapeGroup) -> jnp.ndarray:
        """(trials, N_OBJ) choice probabilities for one shape group."""
        if group.shape not in self._jitted:
            fn = self._choice_probs(group.shape)
            self._jitted[group.shape] = jax.jit(
                lambda p, arrays: jax.vmap(lambda ctx: fn(p, ctx))(arrays)
            )
        return self._jitted[group.shape](dict(params), group.arrays)

    def draws_probs(self, params: Mapping[str, Any], group: ShapeGroup) -> jnp.ndarray:
        """(draws, trials, N_OBJ) probabilities for a batch of parameter draws
        (each value in ``params`` has a leading draw axis)."""
        key = ("draws", group.shape)
        if key not in self._jitted:
            fn = self._choice_probs(group.shape)
            per_draw = lambda p, arrays: jax.vmap(lambda ctx: fn(p, ctx))(arrays)  # noqa: E731
            self._jitted[key] = jax.jit(jax.vmap(per_draw, in_axes=(0, None)))
        return self._jitted[key](dict(params), group.arrays)


def prior_draws(
    params: Mapping[str, Distribution], n: int, seed: int = 0
) -> list[Dict[str, jnp.ndarray]]:
    keys = jax.random.split(jax.random.PRNGKey(seed), len(params))
    samples = {
        name: dist.sample(key, (n,)) for (name, dist), key in zip(params.items(), keys)
    }
    return [{name: v[i] for name, v in samples.items()} for i in range(n)]


def check_contract(
    model: RSAModel,
    groups: Mapping[Tuple[int, int], ShapeGroup],
    *,
    n_draws: int = CONTRACT_DRAWS,
    seed: int = 0,
) -> None:
    """Raise `ModelContractViolation` unless ``model`` meets the contract on ``groups``."""
    params = model.params
    for draw in prior_draws(params, n_draws, seed):
        for shape, group in groups.items():
            n_trials, n_obj = len(group.indices), shape[0]
            where = f"{model.path.name} on {n_obj}-object contexts at params {_fmt(draw)}"
            p = np.asarray(model.group_probs(draw, group))
            if p.shape != (n_trials, n_obj):
                raise ModelContractViolation(
                    f"{where}: choice_probs must return shape (N_OBJ,) = ({n_obj},) per "
                    f"trial; got {p.shape[1:]} per trial"
                )
            if not np.all(np.isfinite(p)):
                raise ModelContractViolation(f"{where}: probabilities are not all finite")
            if p.min() < -NEGATIVE_TOLERANCE:
                raise ModelContractViolation(
                    f"{where}: negative probability {p.min():.3g}"
                )
            worst = float(np.abs(p.sum(axis=1) - 1.0).max())
            if worst > PROBABILITY_SUM_TOLERANCE:
                raise ModelContractViolation(
                    f"{where}: probabilities over objects must sum to 1 (off by {worst:.3g})"
                )
            grads = jax.grad(
                lambda d: jnp.sum(model.group_probs(d, group) ** 2)
            )(draw)
            bad = sorted(k for k, g in grads.items() if not np.all(np.isfinite(np.asarray(g))))
            if bad:
                raise ModelContractViolation(
                    f"{where}: the gradient with respect to {', '.join(bad)} is not finite "
                    f"(NUTS cannot sample it). Common causes: log(0) — add EPS inside the "
                    f"log; a distribution whose weights are all zero for some value (0/0)"
                )


def _fmt(draw: Mapping[str, Any]) -> str:
    return "{" + ", ".join(f"{k}={float(v):.3g}" for k, v in draw.items()) + "}"


def load_models(models_dir: Path, names: Sequence[str]) -> list[RSAModel]:
    return [RSAModel(Path(models_dir) / f"{name}.py", name=name) for name in names]

"""Reference-game contexts and their encoding for memo models.

A context is what one trial shows a listener: a few objects (referents), each
a set of features, and either the one feature word a speaker said (an
*utterance* query) or no informative word (a *prior* query: "mumble", "which
will he pick next?").

Models never see padding. memo enumerates over fixed domains, and padding a
small context out to a common size makes some distribution a 0/0 — harmless in
memo's forward pass (it returns zeros) but NaN in its gradient, which stops
NUTS. So trials are grouped by shape (`group_by_shape`) and each group is
evaluated by a copy of the model compiled with exact-size domains `OBJ` and
`UTT` (`src.rsa.model_file`).

The utterances of a context are the features true of at least one object, in
feature order, plus — when some object has none of them — a final **sink**
utterance true of exactly those objects ("no word applies"). Without it a
speaker who means a featureless object (the plain face of the pragmods simple
game) has no true word, again a 0/0. The sink is never observed, and it adds
no probability to any object a real word is true of, so L0/S1/L1 values on
real words are the textbook ones.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, List, NamedTuple, Optional, Sequence, Tuple

import jax.numpy as jnp
import numpy as np

SINK = "<sink>"


class ContextArrays(NamedTuple):
    """One trial (or, stacked, a group of same-shape trials) as JAX arrays.

    Shapes are for one trial; a group adds a leading trial axis.
    """

    lex: jnp.ndarray  # (N_UTT, N_OBJ) 1.0 where utterance u is true of object r
    is_sink: jnp.ndarray  # (N_UTT,) 1.0 for the sink utterance
    feature_count: jnp.ndarray  # (N_OBJ,) number of context words true of each object
    utterance: jnp.ndarray  # () int32 utterance index heard (0 for a prior query)
    is_prior: jnp.ndarray  # () 1.0 for a prior query (no informative word)
    familiarization: jnp.ndarray  # (N_OBJ,) base rate seen in familiarization, 0..1
    has_familiarization: jnp.ndarray  # () 1.0 when there was a familiarization phase
    grayscale: jnp.ndarray  # (N_OBJ,) 1.0 for an object shown in grayscale
    valence: jnp.ndarray  # () +1 "favorite" framing, -1 "least favorite", 0 neutral


@dataclass(frozen=True)
class Context:
    """One trial's display. ``utterance`` indexes ``feature_names`` (None: prior query)."""

    objects: Tuple[Tuple[int, ...], ...]
    feature_names: Tuple[str, ...]
    utterance: Optional[int]
    item: str = ""
    familiarization: Optional[Tuple[float, ...]] = None
    grayscale: Optional[Tuple[int, ...]] = None
    valence: int = 0
    # Feature indices the speaker can name (the message set). None: every
    # feature is a word (pragmods). In the Franke & Degen game some features
    # (e.g. square, blue) have no word, which changes which inferences hold.
    messages: Optional[Tuple[int, ...]] = None

    def __post_init__(self) -> None:
        objects = tuple(tuple(int(v) for v in row) for row in self.objects)
        object.__setattr__(self, "objects", objects)
        object.__setattr__(self, "feature_names", tuple(self.feature_names))
        if not objects:
            raise ValueError("a context needs at least one object")
        n_features = len(self.feature_names)
        if any(len(row) != n_features for row in objects):
            raise ValueError(
                f"objects must be rectangular with one entry per feature "
                f"({n_features}): {objects}"
            )
        if any(v not in (0, 1) for row in objects for v in row):
            raise ValueError(f"object features must be 0/1: {objects}")
        if self.messages is not None:
            messages = tuple(int(m) for m in self.messages)
            object.__setattr__(self, "messages", messages)
            if not messages or len(set(messages)) != len(messages):
                raise ValueError(f"messages must be distinct feature indices: {messages}")
            if any(not 0 <= m < n_features for m in messages):
                raise ValueError(f"messages {messages} are not all feature indices (0..{n_features - 1})")
        if self.utterance is not None:
            if self.messages is not None and self.utterance not in self.messages:
                raise ValueError(
                    f"utterance {self.feature_names[self.utterance]!r} is not in the message set"
                )
            if not 0 <= self.utterance < n_features:
                raise ValueError(
                    f"utterance {self.utterance} is not a feature index (0..{n_features - 1})"
                )
            if not any(row[self.utterance] for row in objects):
                raise ValueError(
                    f"utterance {self.feature_names[self.utterance]!r} is true of no object"
                )
        for name in ("familiarization", "grayscale"):
            value = getattr(self, name)
            if value is not None:
                value = tuple(value)
                object.__setattr__(self, name, value)
                if len(value) != len(objects):
                    raise ValueError(f"{name} needs one per object: {value}")
        if self.familiarization is not None and not all(
            0.0 <= f <= 1.0 for f in self.familiarization
        ):
            raise ValueError(f"familiarization rates must be in [0, 1]: {self.familiarization}")
        if self.grayscale is not None and any(g not in (0, 1) for g in self.grayscale):
            raise ValueError(f"grayscale must be 0/1 per object: {self.grayscale}")
        if self.valence not in (-1, 0, 1):
            raise ValueError(f"valence must be -1, 0 or 1: {self.valence}")

    @property
    def nameable(self) -> Tuple[int, ...]:
        """Feature indices the speaker can name (every feature without a message set)."""
        return tuple(range(len(self.feature_names))) if self.messages is None else tuple(sorted(self.messages))

    @property
    def present_features(self) -> Tuple[int, ...]:
        """Nameable feature indices true of at least one object: the context's words."""
        return tuple(f for f in self.nameable if any(row[f] for row in self.objects))

    @property
    def needs_sink(self) -> bool:
        """Whether some object has no word true of it (no nameable feature)."""
        return any(not any(row[f] for f in self.nameable) for row in self.objects)

    @property
    def utterance_names(self) -> Tuple[str, ...]:
        names = tuple(self.feature_names[f] for f in self.present_features)
        return names + ((SINK,) if self.needs_sink else ())

    @property
    def shape(self) -> Tuple[int, int]:
        """(N_OBJ, N_UTT): the domain sizes a model is compiled for."""
        return (len(self.objects), len(self.utterance_names))

    def lexicon(self) -> np.ndarray:
        """(N_UTT, N_OBJ) truth table of utterances over objects, sink last."""
        rows = [[row[f] for row in self.objects] for f in self.present_features]
        if self.needs_sink:
            rows.append([int(not any(row[f] for f in self.nameable)) for row in self.objects])
        return np.asarray(rows, dtype=np.float32)

    def choice_classes(self) -> Tuple[int, ...]:
        """Each object's choice class: the index of the first object identical to it.

        Objects with the same features, familiarization rate and colour are
        indistinguishable to every model (they get identical inputs) and, in
        the pragmods data, often to the record of which was chosen. The fit
        observes a choice as its class (`src.rsa.fit.class_probs`).
        """
        keys = [
            (
                row,
                None if self.familiarization is None else self.familiarization[i],
                None if self.grayscale is None else self.grayscale[i],
            )
            for i, row in enumerate(self.objects)
        ]
        return tuple(keys.index(k) for k in keys)

    def arrays(self) -> ContextArrays:
        n_obj, n_utt = self.shape
        lex = self.lexicon()
        is_sink = np.zeros(n_utt, dtype=np.float32)
        if self.needs_sink:
            is_sink[-1] = 1.0
        if self.utterance is None:
            utterance, is_prior = 0, 1.0
        else:
            utterance, is_prior = self.present_features.index(self.utterance), 0.0
        familiarization = (
            np.zeros(n_obj) if self.familiarization is None else np.asarray(self.familiarization)
        )
        grayscale = np.zeros(n_obj) if self.grayscale is None else np.asarray(self.grayscale)
        return ContextArrays(
            lex=jnp.asarray(lex),
            is_sink=jnp.asarray(is_sink),
            feature_count=jnp.asarray((lex * (1 - is_sink)[:, None]).sum(axis=0)),
            utterance=jnp.asarray(utterance, dtype=jnp.int32),
            is_prior=jnp.asarray(is_prior, dtype=jnp.float32),
            familiarization=jnp.asarray(familiarization, dtype=jnp.float32),
            has_familiarization=jnp.asarray(
                float(self.familiarization is not None), dtype=jnp.float32
            ),
            grayscale=jnp.asarray(grayscale, dtype=jnp.float32),
            valence=jnp.asarray(float(self.valence), dtype=jnp.float32),
        )


@dataclass(frozen=True)
class ShapeGroup:
    """Same-shape trials: their positions in the input and their stacked arrays."""

    shape: Tuple[int, int]
    indices: np.ndarray
    arrays: ContextArrays
    classes: np.ndarray  # (trials, N_OBJ) choice class of each object (`Context.choice_classes`)


def stack(arrays: Sequence[ContextArrays]) -> ContextArrays:
    return ContextArrays(*(jnp.stack(field) for field in zip(*arrays)))


def group_by_shape(contexts: Sequence[Context]) -> Dict[Tuple[int, int], ShapeGroup]:
    """Group contexts by (N_OBJ, N_UTT), keeping input order within a group."""
    by_shape: Dict[Tuple[int, int], List[int]] = {}
    for i, ctx in enumerate(contexts):
        by_shape.setdefault(ctx.shape, []).append(i)
    return {
        shape: ShapeGroup(
            shape=shape,
            indices=np.asarray(idx),
            arrays=stack([contexts[i].arrays() for i in idx]),
            classes=np.asarray([contexts[i].choice_classes() for i in idx], dtype=np.int32),
        )
        for shape, idx in sorted(by_shape.items())
    }


def model_key(ctx: Context) -> tuple:
    """What a model sees of a context: two contexts with equal keys get equal
    `Context.arrays` and choice classes (item and feature names are labels)."""
    return (ctx.objects, ctx.utterance, ctx.familiarization, ctx.grayscale, ctx.valence, ctx.nameable)


def unique_contexts(contexts: Sequence[Context]) -> Tuple[List[Context], np.ndarray]:
    """The distinct contexts (by `model_key`, first occurrence order) and each
    input's index among them.

    Many trials show the same display (every participant of a condition), so
    a model is evaluated once per distinct display and the result gathered
    per trial: on the combined data 40k trials are 3k displays.
    """
    index: Dict[tuple, int] = {}
    uniques: List[Context] = []
    inverse = np.empty(len(contexts), dtype=np.int64)
    for i, ctx in enumerate(contexts):
        key = model_key(ctx)
        if key not in index:
            index[key] = len(uniques)
            uniques.append(ctx)
        inverse[i] = index[key]
    return uniques, inverse

"""Admission of a theorist's theory to the open loop (the closed loop's `src.rsa.loop.gates`, for
theories fitted to every paradigm of the chain).

A candidate directory holds ``candidate.py`` (a theory: ``PARAMS``, ``listener(params, ctx)``
and optionally ``speaker(params, ctx)``, `src.rsa_open.fit.TheoryModel`) and ``hypothesis.md``.
It is admitted only if, in order:

1. the code gate passes (`src.rsa.loop.code_gate`);
2. it is a theory, not a model of one paradigm: it defines ``listener`` and no
   ``choice_probs``, and none of its parameters is a link's (temperature, lapse and the
   links' own: the response process belongs to the paradigm, `src.rsa_open.links`);
3. it loads and meets the **listener contract** (`src.rsa.model_file.check_contract`) and the
   **speaker contract** (`check_speaker_contract`: every target's distribution over the
   scene's real messages, the sink never said, finite gradients) on every scene of the corpus
   and of the novelty pool;
4. its fit to the corpus (every block, `src.rsa_open.loop.fitting.loop_fit`) finishes within
   the time limit, gives no observed response probability zero and converges (after the one
   refit);
5. it is novel: its posterior-mean predictions on the novelty pool, listener and speaker
   both, are at least the threshold (RMSE) from every admitted theory's.

Every refusal carries a reason written for the agent that will repair it; infrastructure
failures raise.
"""

from __future__ import annotations

import ast
from dataclasses import dataclass
from pathlib import Path
from typing import Mapping, Optional, Sequence

import jax
import jax.numpy as jnp
import numpy as np

from src.rsa.context import Context, group_by_shape, unique_contexts
from src.rsa.fit import FitSettings, class_probs, draw_batches
from src.rsa.loop.code_gate import code_problems
from src.rsa.loop.fitting import ModelFailure, is_model_failure
from src.rsa.loop.gates import read_candidate
from src.rsa.loop.novelty import closest
from src.rsa.model_file import ModelContractViolation, check_contract, prior_draws
from src.rsa_open.corpus import Block, CorpusFit
from src.rsa_open.fit import TheoryModel
from src.rsa_open.loop.fitting import loop_fit

MAX_POOL_DRAWS = 100
SPEAKER_SUM_TOLERANCE = 1e-4


@dataclass
class Admission:
    admitted: bool
    reason: str
    fit: Optional[CorpusFit] = None
    pool_preds: Optional[np.ndarray] = None


@dataclass(frozen=True)
class GateConfig:
    corpus_path: Path
    cache_dir: Path
    settings: FitSettings
    novelty_threshold: float
    time_limit_sec: Optional[float]


def _refuse(reason: str, **kw) -> Admission:
    return Admission(False, reason, **kw)


def link_parameter_names() -> set:
    from src.rsa_open.links import LINKS, likelihood

    from src.rsa_open.links import SECOND_PREFIX

    names = {k for name in LINKS for k in likelihood(name, scale_points=5, total_points=100).params}
    return names | {SECOND_PREFIX + k for k in names}  # a two-measure paradigm's second link


def theory_shape_problems(source: str) -> list:
    """Why a file is not a paradigm-free theory (empty when it is one)."""
    tree = ast.parse(source)
    defined = {n.name for n in tree.body if isinstance(n, ast.FunctionDef)}
    problems = []
    if "listener" not in defined:
        problems.append("it defines no listener(params, ctx)")
    if "choice_probs" in defined:
        problems.append("it defines choice_probs: a theory gives the listener's posterior (listener) and, if "
                        "it likes, the speaker (speaker); the paradigm's link turns them into responses")
    return problems


def check_speaker_contract(theory: TheoryModel, groups, *, n_draws: int = 2, seed: int = 0) -> None:
    """Raise `ModelContractViolation` unless the theory's speaker (its own or the derived one) is,
    for every target, a distribution over the scene's real messages with finite gradients."""
    for draw in prior_draws(theory.params, n_draws, seed) if theory.params else [{}]:
        for shape, group in groups.items():
            n_obj, n_utt = shape
            where = f"{theory.path.name}'s speaker on {n_obj}-object scenes"
            s = np.asarray(theory.group_speaker(draw, group))
            if s.shape != (len(group.indices), n_utt, n_obj):
                raise ModelContractViolation(f"{where}: speaker must return shape (N_UTT, N_OBJ) = ({n_utt}, {n_obj}) "
                                             f"per trial; got {s.shape[1:]}")
            if not np.all(np.isfinite(s)) or s.min() < -1e-6:
                raise ModelContractViolation(f"{where}: probabilities are not all finite and non-negative")
            sink = np.asarray(group.arrays.is_sink) > 0
            if np.any(s[np.broadcast_to(sink[..., None], s.shape)] > 1e-6):
                raise ModelContractViolation(f"{where}: the sink ('no word applies') must have probability 0")
            worst = float(np.abs(s.sum(axis=1) - 1.0).max())
            if worst > SPEAKER_SUM_TOLERANCE:
                raise ModelContractViolation(f"{where}: each target's probabilities over messages must sum to 1 "
                                             f"(off by {worst:.3g})")
            if theory.params:
                grads = jax.grad(lambda d: jnp.sum(theory.group_speaker(d, group) ** 2))(draw)
                bad = sorted(k for k, g in grads.items() if not np.all(np.isfinite(np.asarray(g))))
                if bad:
                    raise ModelContractViolation(f"{where}: the gradient with respect to {', '.join(bad)} is not finite")


def pool_predictions(theory: TheoryModel, fitted: CorpusFit, pool: Sequence[Context],
                     max_draws: int = MAX_POOL_DRAWS) -> np.ndarray:
    """Posterior-mean listener class probabilities and speaker probabilities over the pool,
    flattened; raises ValueError when they are not finite."""
    flat = fitted.flat()
    params = {k: flat[k] for k in theory.params}
    n = len(next(iter(flat.values())))
    take = np.unique(np.linspace(0, n - 1, min(n, max_draws)).round().astype(int))
    parts = []
    for group in group_by_shape(pool).values():
        if params:
            acc_l, acc_s = 0.0, 0.0
            for k, batch in draw_batches(params, take):
                acc_l = acc_l + np.asarray(class_probs(theory.draws_probs(batch, group), group.classes)[:k],
                                           dtype=np.float64).sum(axis=0)
                acc_s = acc_s + np.asarray(theory.draws_speaker(batch, group)[:k], dtype=np.float64).sum(axis=0)
            listener, speaker = acc_l / len(take), acc_s / len(take)
        else:
            listener = np.asarray(class_probs(theory.group_probs({}, group)[None], group.classes)[0])
            speaker = np.asarray(theory.group_speaker({}, group))
        parts += [listener.reshape(-1), speaker.reshape(-1)]
    preds = np.concatenate(parts)
    if not np.all(np.isfinite(preds)):
        raise ValueError(f"{theory.name}'s predictions are not finite on some novelty-pool scenes")
    return preds


def admit(candidate_dir: Path, name: str, *, cfg: GateConfig, blocks: Sequence[Block], pool: Sequence[Context],
          admitted_preds: Mapping[str, np.ndarray]) -> Admission:
    candidate_dir = Path(candidate_dir)
    missing = read_candidate(candidate_dir)
    if missing:
        return _refuse(missing)
    path = candidate_dir / "candidate.py"
    source = path.read_text(encoding="utf-8")
    problems = code_problems(source)
    if problems:
        return _refuse("the code gate refused candidate.py: " + ", ".join(problems) +
                       ". Theory files may import jax, memo, numpyro, numpy, a few stdlib modules and "
                       "src.rsa.memo_kit only, and may not read files or reach the interpreter.")
    try:
        shape = theory_shape_problems(source)
    except SyntaxError as exc:
        return _refuse(f"candidate.py is not valid Python: {exc}")
    if shape:
        return _refuse("candidate.py is not a theory: " + "; ".join(shape))
    try:
        theory = TheoryModel(path, name=name)
        clash = sorted(set(theory.params) & link_parameter_names())
        if clash:
            return _refuse(f"its parameters {clash} belong to the links (each paradigm's response process: "
                           f"a decision temperature, a lapse, a rating's cutpoints); rename or remove them")
        scenes = unique_contexts([c for b in blocks for c in b.contexts])[0]
        for groups in (group_by_shape(scenes), group_by_shape(pool)):
            check_contract(theory, groups)
            check_speaker_contract(theory, groups)
    except ModelContractViolation as exc:
        return _refuse(f"contract: {exc}")
    except Exception as exc:  # memo compile errors, errors in the theory's own code
        if is_model_failure(exc, path):
            return _refuse(f"the theory failed to load or run: {type(exc).__name__}: {exc}")
        raise
    try:
        fitted = loop_fit(path, name, cfg.corpus_path, cfg.settings, cfg.cache_dir, time_limit_sec=cfg.time_limit_sec)
    except ModelFailure as exc:
        return _refuse(f"fitting failed: {exc}")
    if not fitted.converged:
        report = fitted.sampler_report()
        return _refuse("the fit did not converge (a near miss, R-hat ≤ 1.2, bulk ESS ≥ 20 and at most 2% divergent, "
                       "is refitted once at target_accept 0.95; a fit further off is not): "
                       + "; ".join(fitted.convergence_problems) + ". " + (report.text() + ". " if report else "")
                       + "Reparameterise (remove parameters the data cannot separate, sample on an unconstrained "
                       "scale, tighten priors) rather than relying on smaller steps.", fit=fitted)
    try:
        preds = pool_predictions(theory, fitted, pool)
    except ValueError as exc:
        return _refuse(str(exc), fit=fitted)
    nearest, dist = closest(preds, admitted_preds)
    if dist < cfg.novelty_threshold:
        return _refuse(f"not novel: its listener and speaker predictions are within RMSE {dist:.4f} of {nearest}'s "
                       f"(threshold {cfg.novelty_threshold}) over the novelty pool of {len(pool)} scenes. A "
                       f"re-parameterisation of an existing mechanism is not a new hypothesis; change what the "
                       f"listener or speaker computes.", fit=fitted, pool_preds=preds)
    return Admission(True, "admitted", fit=fitted, pool_preds=preds)
